def bubble_cmp(items):
    items, n = list(items), 0
    swapped = True
    while swapped:
        swapped = False
        for i in range(len(items) - 1):
            n += 1
            if items[i] > items[i + 1]:
                items[i], items[i + 1] = items[i + 1], items[i]
                swapped = True
    return n

def merge_cmp(items):
    if len(items) <= 1:
        return list(items), 0
    mid = len(items) // 2
    left, a = merge_cmp(items[:mid])
    right, b = merge_cmp(items[mid:])
    res, i, j, n = [], 0, 0, 0
    while i < len(left) and j < len(right):
        n += 1
        if left[i] <= right[j]:
            res.append(left[i]); i += 1
        else:
            res.append(right[j]); j += 1
    res += left[i:] + right[j:]
    return res, a + b + n
